/* Russian production grade handbook — steels, verified GOST grade families, machining commentary distinct from standards. */
(()=>{'use strict';const d=window.CNC_DATA;if(!d)return;Object.assign(d.sources,{"grade-gost380":{"name":"Росстандарт — ГОСТ 380-2005, сталь обыкновенного качества","url":"https://protect.gost.ru/gost/details/6c99c390-1cc9-44d5-84c3-f9c1276df24f","details":"Нормативное обозначение марок группы Ст, химический состав"},"grade-gost1050":{"name":"Росстандарт — ГОСТ 1050-2013, качественные нелегированные конструкционные стали","url":"https://protect.gost.ru/gost/details/c4fa5bc1-a80f-42a5-b551-19a62b619715","details":"Марки, технические требования и химический состав конструкционных сталей"},"grade-gost19281":{"name":"Росстандарт — ГОСТ 19281-2014, прокат повышенной прочности","url":"https://protect.gost.ru/gost/details/70f2c2d1-8390-4c37-840c-735e0654f3e2","details":"Категории и требования к низколегированному конструкционному прокату; новая редакция 19281-2025 вводится с 01.12.2026"},"grade-gost4543":{"name":"Росстандарт — ГОСТ 4543-2016, конструкционные легированные стали","url":"https://protect.gost.ru/gost/details/c92d1dfe-647b-4048-9f69-400b4bf98888","details":"Конструкционные легированные стали и технические требования"},"grade-gost14959":{"name":"Росстандарт — ГОСТ 14959-2016, рессорно-пружинная сталь","url":"https://protect.gost.ru/gost/details/25b96c57-e48e-4aa0-b616-f70be1057e75","details":"Марки рессорно-пружинных сталей и требования к поставке"},"grade-gost801":{"name":"Росстандарт — ГОСТ 801-2022, прокат из подшипниковой стали","url":"https://protect.gost.ru/gost/details/23a033f0-fd09-41fa-840b-47d845668e37","details":"Взамен ГОСТ 801-78; подшипниковые стали, структура и включения"},"grade-gost5632":{"name":"Росстандарт — ГОСТ 5632-2014, коррозионностойкие стали","url":"https://protect.gost.ru/gost/details/d6ac3954-d07e-4a10-a038-f3ab9b1d5b7b","details":"Марки аустенитных, мартенситных и других коррозионностойких сталей"},"grade-gost5950":{"name":"Росстандарт — ГОСТ 5950-2000, инструментальная легированная сталь","url":"https://protect.gost.ru/gost/details/5629eb42-1231-44ab-9578-2908e5fe7fb8","details":"Инструментальные стали и требования к металлопродукции"},"grade-gost19265":{"name":"Росстандарт — ГОСТ 19265-73, быстрорежущая сталь","url":"https://protect.gost.ru/gost/details/85632040-cb6c-4f5e-a7d6-66dbfefe570b","details":"Прутки и полосы из быстрорежущей стали"}});d.materialGradeAtlas=d.materialGradeAtlas||[];const grades=[{"id":"mat-grade-steel-01","name":"Ст3сп","family":"carbon","group":"Стали","subgroup":"Углеродистые стали","std":"ГОСТ 380-2005, сталь обыкновенного качества","source":"grade-gost380","overview":"Низкоуглеродистая конструкционная сталь обыкновенного качества. Ст3 — условный номер марки; «сп» означает спокойную сталь, а не специальную химическую добавку. Часто встречается в сварных каркасах, плитах и кронштейнах.","state":"Обычно оценивают состояние горячекатаного проката: окалина, остаточные напряжения и отклонения формы могут сильнее влиять на первый проход, чем номинальная прочность.","behavior":"При исправном инструменте режется сравнительно предсказуемо, но тонкие стенки и большие плиты способны деформироваться после освобождения из тисков.","tool":"На первичном проходе предусмотрительно оцени корку и прерывистый контакт; для чистовой контролируй равномерность припуска и опоры.","risk":"Повышенная шероховатость из-за нароста на кромке; коробление больших деталей; локальные сколы на окалине.","checks":"Стандарт и состояние раскисления; лист или профиль; наличие окалины; плоскостность свободной детали.","link":"mat-grade-steel-01","linked":["mat-stress","mat-hardness","mat-material-selection"]},{"id":"mat-grade-steel-02","name":"Сталь 10","family":"carbon","group":"Стали","subgroup":"Углеродистые стали","std":"ГОСТ 1050-2013, качественные нелегированные конструкционные стали","source":"grade-gost1050","overview":"Малоуглеродистая качественная конструкционная сталь. Марка «10» — ориентир по содержанию углерода порядка 0,10%, но реальные пределы состава берут из стандарта и сертификата.","state":"В зависимости от состояния и обработки поверхность может быть довольно пластичной. Не путай с цементованным изделием из стали 10: поверхностная твёрдость у него иная.","behavior":"Вязкая длинная стружка и склонность к налипанию могут быть важнее высокой твёрдости. Для тонкого финишного среза требуется достаточно острая кромка.","tool":"Убедись, что канавки фрезы и СОЖ справляются с эвакуацией длинной стружки; на финише избегай продолжительного затирания.","risk":"Налипание и рваный край при неверной геометрии; заусенец на выходе; следы от стружки в кармане.","checks":"Состояние поставки, поверхностная обработка, требуемые допуски, наличие заусенцев.","link":"mat-grade-steel-02","linked":["mat-surface-layer","mat-hardness","mat-material-selection"]},{"id":"mat-grade-steel-03","name":"Сталь 20","family":"carbon","group":"Стали","subgroup":"Углеродистые стали","std":"ГОСТ 1050-2013, качественные нелегированные конструкционные стали","source":"grade-gost1050","overview":"Качественная конструкционная углеродистая сталь. Одна из часто применяемых малоуглеродистых сталей для деталей машин; цифра отражает приблизительную углеродистость, а не фактическую твёрдость.","state":"В сыром и нормализованном состоянии свойства отличаются; после цементации поверхность может быть намного твёрже сердцевины.","behavior":"При сравнительно невысокой твёрдости режущая кромка может страдать от налипания, а при наличии твёрдого слоя — от неоднородного контакта.","tool":"Для поверхности после цементации не используй режимы, отработанные по мягкой сердцевине. На обычном прокате подбирай инструмент для сталей группы P.","risk":"Заусенцы и длинная стружка в мягком состоянии; повреждение кромки при проходе через твёрдый слой.","checks":"Состояние детали до или после химико-термической обработки; сертификат; HRC поверхности и сердцевины по требованию.","link":"mat-grade-steel-03","linked":["mat-case-hardening","mat-hardness","mat-material-selection"]},{"id":"mat-grade-steel-04","name":"Сталь 35","family":"carbon","group":"Стали","subgroup":"Углеродистые стали","std":"ГОСТ 1050-2013, качественные нелегированные конструкционные стали","source":"grade-gost1050","overview":"Среднеуглеродистая конструкционная сталь. По углероду располагается между сталями 20 и 45; применяется для деталей машин с требованиями к прочности и термообработке.","state":"Нормализация, отжиг и закалка с отпуском приводят к разным твёрдостям и структурам, при одинаковой маркировке стали.","behavior":"При росте прочности повышается нагрузка на кромку; на черновой важен стабильный контакт, на чистовой — отсутствие отжима.","tool":"Выбирай исходную подгруппу ISO P по документированному состоянию, проверяй вылет фрезы и реальный ae в переходах.","risk":"Скол при непостоянном припуске; увод размера из-за прогиба; перегрев при неоправданно высокой Vc.","checks":"Сертификат, состояние поставки, твердость, число зубьев, жёсткость закрепления.","link":"mat-grade-steel-04","linked":["mat-hardness","mat-hardness","mat-material-selection"]},{"id":"mat-grade-steel-05","name":"Сталь 40","family":"carbon","group":"Стали","subgroup":"Углеродистые стали","std":"ГОСТ 1050-2013, качественные нелегированные конструкционные стали","source":"grade-gost1050","overview":"Среднеуглеродистая качественная сталь, НЕ 40Х. Без буквы «Х» в названии — углеродистая сталь с ориентиром на 0,40% C. Это отдельная марка, а не сокращение 40Х.","state":"После нормализации, отжига, закалки и отпуска обрабатываемость меняется. Хромистая 40Х может иметь другую прокаливаемость и требовать иной технологии.","behavior":"В нормализованном состоянии обычно обрабатывается как среднеуглеродистая сталь группы P. При повышенной твёрдости важны прочность кромки и недопущение локального полного паза.","tool":"При построении процесса сразу разделяй 40 и 40Х в спецификации CAM. Не переносить автоматически найденные режимы для 40Х на сталь 40.","risk":"Ошибочная идентификация марки; непредсказуемый скол после термообработки; сильный перегрев при большой контактной зоне.","checks":"Проверь буквально записанную марку в чертеже и сертификате, HRC/HBW после термообработки и требования к структуре.","link":"mat-grade-steel-05","linked":["mat-steel-40kh","mat-hardness","mat-material-selection"]},{"id":"mat-grade-steel-06","name":"Сталь 45","family":"carbon","group":"Стали","subgroup":"Углеродистые стали","std":"ГОСТ 1050-2013, качественные нелегированные конструкционные стали","source":"grade-gost1050","overview":"Очень распространённая качественная среднеуглеродистая сталь. Используется для валов, осей, шестерён и различных механических деталей. Номер указывает ориентир на массовую долю углерода порядка 0,45%.","state":"На практике встречается в нормализованном, отожжённом, улучшенном или поверхностно закалённом состоянии; разница существенна.","behavior":"На фрезеровании образует иной характер стружки и сил по сравнению с мягкой сталью 20. Если обработка ведётся после ТВЧ, учитывай градиент твёрдости.","tool":"При черновой оцени припуск и жёсткость; при чистовой — реальные силы и состояние поверхностного слоя, особенно после закалки.","risk":"Ускоренный износ на упрочнённой поверхности; недостаточная плоскостность после снятия напряжений; перегрузка в углу.","checks":"HBW/HRC по нужной глубине, история термообработки, характер припуска и корки.","link":"mat-grade-steel-06","linked":["mat-case-hardening","mat-hardness","mat-material-selection"]},{"id":"mat-grade-steel-07","name":"09Г2С","family":"lowalloy","group":"Стали","subgroup":"Низколегированные стали","std":"ГОСТ 19281-2014, прокат повышенной прочности","source":"grade-gost19281","overview":"Низколегированная конструкционная сталь повышенной прочности. Распространена в сварных конструкциях и прокате. Обозначение указывает на низкое содержание C с добавками марганца и кремния.","state":"Механические свойства зависят от толщины проката, категории поставки, технологии и термообработки; нельзя без уточнения считать её «всегда такой же, как Ст3».","behavior":"Технология фрезерования часто близка конструкционным сталям ISO P, но сварные детали могут иметь твёрдые локальные зоны, окалину и остаточные напряжения.","tool":"Если фрезеруешь уже сваренную раму, учитывай зону термического влияния и деформацию после освобождения зажима.","risk":"Разная стойкость у шва и основного металла; коробление крупных плит; вибрации на неравномерной заготовке.","checks":"Состояние сварки, прокат, толщина, сертификат; текущая редакция ГОСТ 19281-2014 до 01.12.2026.","link":"mat-grade-steel-07","linked":["mat-stress","mat-hardness","mat-material-selection"]},{"id":"mat-grade-steel-08","name":"20Х","family":"alloy","group":"Стали","subgroup":"Легированные стали","std":"ГОСТ 4543-2016, конструкционные легированные стали","source":"grade-gost4543","overview":"Низкоуглеродистая легированная хромистая конструкционная сталь. Хромистая сталь, часто применяемая для деталей, которые затем цементуют или поверхностно упрочняют, сохраняя вязкую сердцевину.","state":"Маршрут «мягкая обработка → цементация → закалка → финиш» принципиально отличается от фрезерования готовой упрочнённой поверхности.","behavior":"До упрочнения контролируй пластичную стружку и форму. После — градиент твёрдости и инструментальный материал на участке входа.","tool":"На чертеже ищи требования к глубине цементованного слоя и к размерам до/после термообработки. Технологический припуск назначается по маршруту.","risk":"Скол при прохождении твёрдой корки; потеря функционального слоя от лишнего прохода; коробление после закалки.","checks":"Режим цементации, эффективная глубина слоя, твёрдость поверхности/сердцевины, предельный припуск.","link":"mat-grade-steel-08","linked":["mat-case-hardening","mat-hardness","mat-material-selection"]},{"id":"mat-grade-steel-09","name":"65Г","family":"spring","group":"Стали","subgroup":"Пружинные стали","std":"ГОСТ 14959-2016, рессорно-пружинная сталь","source":"grade-gost14959","overview":"Рессорно-пружинная марганцовистая сталь. Высокоуглеродистая пружинная сталь, востребованная в упругих деталях, пластинах и элементах пружинной оснастки.","state":"Состояние после проката, отжига и закалки с отпуском совершенно разное; готовые упругие пластины могут сильно деформироваться при зажиме.","behavior":"При высокой твёрдости растёт риск скола; у тонкой детали основным ограничением становится удержание формы при снятии металла.","tool":"До выбора фрезы проверь целевую твёрдость, профиль детали, её опоры и момент отпуска в техпроцессе.","risk":"Конусность и прогиб тонких пластин; трещины в материале после неверной термообработки; выкрашивание кромки.","checks":"Состояние, HRC по спецификации, толщина детали, способ фиксации без избыточной деформации.","link":"mat-grade-steel-09","linked":["mat-heat-treat","mat-hardness","mat-material-selection"]},{"id":"mat-grade-steel-10","name":"ШХ15","family":"bearing","group":"Стали","subgroup":"Подшипниковые стали","std":"ГОСТ 801-2022, прокат из подшипниковой стали","source":"grade-gost801","overview":"Высокоуглеродистая хромистая подшипниковая сталь. Используется для тел качения, колец и высоконагруженных точных деталей. Важны не только твёрдость, но и карбидная структура, чистота и включения.","state":"В сфероидизированном состоянии может обрабатываться до закалки; после получения рабочей высокой твёрдости методы и инструмент радикально отличаются.","behavior":"Из-за карбидов и твёрдости определяющими становятся износостойкость кромки, геометрия и строго контролируемые припуски.","tool":"Разделяй обработку мягкой заготовки и окончательной подшипниковой детали после термообработки. Не ориентируйся на одну цифру HRC.","risk":"Быстрый износ на мелких твёрдых частицах; скол на прерывистом резании; перегрев на финише.","checks":"ГОСТ 801-2022, состояние поставки, чистота и структура по требованиям, HRC и качество поверхности.","link":"mat-grade-steel-10","linked":["mat-hardness","mat-hardness","mat-material-selection"]},{"id":"mat-grade-steel-11","name":"08Х18Н10","family":"stainless","group":"Стали","subgroup":"Нержавеющие стали","std":"ГОСТ 5632-2014, коррозионностойкие стали","source":"grade-gost5632","overview":"Аустенитная коррозионностойкая хромоникелевая сталь. Распространённая Cr–Ni нержавеющая сталь группы M. Сравнима по типу структуры с 12Х18Н10Т, но не тождественна ей по составу и назначению.","state":"В отожжённом состоянии структура обычно аустенитная. Холодная деформация может увеличить прочность и изменить реакцию на инструмент.","behavior":"Склонность к наклёпу и налипанию; относительно невысокая теплопроводность усиливает тепловую нагрузку на кромке.","tool":"Подбирай геометрию под группу M, не допускай повторного затирания, проверяй достаточную толщину стружки и направление СОЖ.","risk":"Рваная поверхность, стойкий нарост и ухудшение финиша при слишком малом срезе.","checks":"Подтверди 08Х18Н10 vs 12Х18Н10Т, исходный наклёп, состояние/поверхность и требования к коррозионной стойкости.","link":"mat-grade-steel-11","linked":["mat-stainless-12kh18n10t","mat-hardness","mat-material-selection"]},{"id":"mat-grade-steel-12","name":"20Х13","family":"stainless","group":"Стали","subgroup":"Нержавеющие стали","std":"ГОСТ 5632-2014, коррозионностойкие стали","source":"grade-gost5632","overview":"Мартенситная коррозионностойкая хромистая сталь. Отличается от аустенитных Cr–Ni сталей: допускает термическое упрочнение, и её обрабатываемость сильно зависит от этого состояния.","state":"В отожжённом и закалённо-отпущенном состоянии будет иной набор HRC, микроструктуры и сил резания.","behavior":"В мягком состоянии подбирают инструмент как для соответствующей хромистой стали; после упрочнения кромка должна выдерживать более высокую нагрузку.","tool":"Обязательно уточняй состояние, прежде чем применять режимы из «нержавейки 304».","risk":"Ускоренный износ после закалки; сколы на прерывистом контуре; несоответствие финишной геометрии из-за прогиба.","checks":"Термообработка, фактическая HRC, требования к коррозионной стойкости и точности.","link":"mat-grade-steel-12","linked":["mat-stainless-families","mat-hardness","mat-material-selection"]},{"id":"mat-grade-steel-13","name":"40Х13","family":"stainless","group":"Стали","subgroup":"Нержавеющие стали","std":"ГОСТ 5632-2014, коррозионностойкие стали","source":"grade-gost5632","overview":"Высокоуглеродистая мартенситная хромистая сталь. Встречается в деталях, где нужны повышенная твёрдость и коррозионная стойкость; не является эквивалентом 40Х.","state":"После закалки может быть существенно твёрже сырой хромистой стали; характер карбидов и отпуск определяют износ инструмента.","behavior":"При большой твёрдости работа фрезы ограничивается прочностью режущей кромки и нагревом, особенно на острых внутренних углах.","tool":"Сначала проверь HRC и режущий материал, затем решай, допустима ли монолитная фреза на нужной осевой глубине.","risk":"Микросколы после ударных входов, термический износ, нестабильный размер.","checks":"Не перепутай с 40Х; проверь структурное состояние, HRC и рабочую длину фрезы.","link":"mat-grade-steel-13","linked":["mat-steel-40kh","mat-hardness","mat-material-selection"]},{"id":"mat-grade-steel-14","name":"95Х18","family":"stainless","group":"Стали","subgroup":"Нержавеющие стали","std":"ГОСТ 5632-2014, коррозионностойкие стали","source":"grade-gost5632","overview":"Высокоуглеродистая мартенситная коррозионностойкая сталь. Марка с высоким содержанием хрома и углерода, в структуре которой важны твёрдые карбиды; применяется для износостойких деталей.","state":"В отожжённом состоянии обрабатывается совсем иначе, чем после закалки и отпуска. Поверхностная твёрдость не описывает распределение карбидов.","behavior":"При фрезеровании в упрочнённом состоянии риск абразивного износа и скола повышается; режим выбирают под конкретный инструмент.","tool":"Не переносить методы от аустенитной 12Х18Н10Т: её трудности — наклёп и пластичность, а здесь также доминируют твёрдые частицы.","risk":"Сколы и абразивный износ на карбидах; задиры при изношенной кромке.","checks":"Состояние, структура и карбиды, разрешённая твёрдость, инструмент и качество финиша.","link":"mat-grade-steel-14","linked":["mat-stainless-families","mat-hardness","mat-material-selection"]},{"id":"mat-grade-steel-15","name":"Х12МФ","family":"tool","group":"Стали","subgroup":"Инструментальные стали","std":"ГОСТ 5950-2000, инструментальная легированная сталь","source":"grade-gost5950","overview":"Высокохромистая инструментальная сталь холодной работы. Используется для штампов и износостойкой оснастки. Крупные и мелкие карбиды существенно влияют на поведение при обработке.","state":"До закалки и после неё применяются разные стратегии; после термообработки нередко требуется окончательная точная обработка твёрдого инструмента.","behavior":"Повышенная абразивность и возможная неоднородность структуры дают износ и сколы; необходимо согласовывать обработку с предполагаемой последующей термообработкой.","tool":"Для карманов и формообразующих поверхностей анализируй твёрдость, карбидность, слабые участки и равномерность припуска.","risk":"Выкрашивание кромки на включениях, нестабильная шероховатость, коробление после закалки.","checks":"Состояние отжига/закалки, структура по техтребованиям, режим отпуска и материал фрезы.","link":"mat-grade-steel-15","linked":["mat-microstructure","mat-hardness","mat-material-selection"]},{"id":"mat-grade-steel-16","name":"9ХС","family":"tool","group":"Стали","subgroup":"Инструментальные стали","std":"ГОСТ 5950-2000, инструментальная легированная сталь","source":"grade-gost5950","overview":"Легированная инструментальная сталь для режущего и мерительного инструмента. Сталь с хромом и кремнием, применяемая для инструмента и точной оснастки; изготавливают в разных термообработанных состояниях.","state":"После отжига можно готовить геометрию, а последующая закалка приводит к иной стойкости и размерному состоянию.","behavior":"Для фрезеровщика критичны твёрдость, условия резания и требования к точности после термообработки.","tool":"Учитывай изменение размеров после закалки и возможное наличие твёрдых участков на поверхности.","risk":"Сколы после закалки, быстрый износ, уход размера при снятии напряжений.","checks":"Фактическая HRC, термообработка, маршрут последующей доводки, оставленный припуск.","link":"mat-grade-steel-16","linked":["mat-heat-treat","mat-hardness","mat-material-selection"]},{"id":"mat-grade-steel-17","name":"Р6М5","family":"highspeed","group":"Стали","subgroup":"Быстрорежущие стали","std":"ГОСТ 19265-73, быстрорежущая сталь","source":"grade-gost19265","overview":"Быстрорежущая инструментальная сталь. Классическая быстрорежущая сталь для режущих инструментов; название связано с её легированием, а не обозначением обычной конструкционной стали.","state":"До упрочнения это заготовка инструмента, после правильной термообработки — твёрдый материал с карбидами и стойкостью при нагреве.","behavior":"На фрезеровании уже закалённой Р6М5 возможны значительные трудности; не применять к ней режимы обычных конструкционных сталей.","tool":"Если производишь фрезу или резец из Р6М5, отдельно проектируй мягкую обработку, термообработку и последующую точную обработку.","risk":"Абразивный износ, скол твёрдой кромки, потеря качества при перегреве.","checks":"Режим закалки/отпуска, измеренная HRC, карбидность, контроль формы.","link":"mat-grade-steel-17","linked":["mat-hardness","mat-hardness","mat-material-selection"]}];const articles=[{"id":"mat-grade-steel-01","cat":"materials","title":"Ст3сп — свойства и особенности фрезерования","subtitle":"Углеродистые стали","quick":"Низкоуглеродистая конструкционная сталь обыкновенного качества. Ст3 — условный номер марки; «сп» означает спокойную сталь, а не специальную химическую добавку. Часто встречается в сварных каркасах, плитах и кронштейнах.","tags":["Ст3сп","Ст3сп","Углеродистые стали","материал","марочник","обрабатываемость","режимы"],"time":11,"actions":["Проверь сертификат материала и нормируемое состояние, а не только название марки.","Сверь реальную твёрдость, структуру, форму и состояние наружного слоя.","Выбирай инструмент и режимы по подтверждённой группе и каталогу для конкретной операции.","Контролируй нагрузку, геометрию после разжима и характер износа."],"sections":[{"h":"Что это за марка","p":"Низкоуглеродистая конструкционная сталь обыкновенного качества. Ст3 — условный номер марки; «сп» означает спокойную сталь, а не специальную химическую добавку. Часто встречается в сварных каркасах, плитах и кронштейнах."},{"h":"Состояние и термообработка","p":"Обычно оценивают состояние горячекатаного проката: окалина, остаточные напряжения и отклонения формы могут сильнее влиять на первый проход, чем номинальная прочность."},{"h":"Как ведёт себя при фрезеровании","p":"При исправном инструменте режется сравнительно предсказуемо, но тонкие стенки и большие плиты способны деформироваться после освобождения из тисков."},{"h":"Инструмент и выбор технологии","p":"На первичном проходе предусмотрительно оцени корку и прерывистый контакт; для чистовой контролируй равномерность припуска и опоры."},{"h":"Типичные дефекты и причины","p":"Повышенная шероховатость из-за нароста на кромке; коробление больших деталей; локальные сколы на окалине."},{"h":"Что проверить перед обработкой","p":"Стандарт и состояние раскисления; лист или профиль; наличие окалины; плоскостность свободной детали. Важное ограничение: названия ГОСТ задают класс продукции и требования; реальные режимы резания и дефекты — технологические выводы, не табличные значения из стандарта."}],"linked":["mat-stress","mat-hardness","mat-material-selection"],"sources":["grade-gost380","mat-author"]},{"id":"mat-grade-steel-02","cat":"materials","title":"Сталь 10 — свойства и особенности фрезерования","subtitle":"Углеродистые стали","quick":"Малоуглеродистая качественная конструкционная сталь. Марка «10» — ориентир по содержанию углерода порядка 0,10%, но реальные пределы состава берут из стандарта и сертификата.","tags":["Сталь 10","10","Углеродистые стали","материал","марочник","обрабатываемость","режимы"],"time":11,"actions":["Проверь сертификат материала и нормируемое состояние, а не только название марки.","Сверь реальную твёрдость, структуру, форму и состояние наружного слоя.","Выбирай инструмент и режимы по подтверждённой группе и каталогу для конкретной операции.","Контролируй нагрузку, геометрию после разжима и характер износа."],"sections":[{"h":"Что это за марка","p":"Малоуглеродистая качественная конструкционная сталь. Марка «10» — ориентир по содержанию углерода порядка 0,10%, но реальные пределы состава берут из стандарта и сертификата."},{"h":"Состояние и термообработка","p":"В зависимости от состояния и обработки поверхность может быть довольно пластичной. Не путай с цементованным изделием из стали 10: поверхностная твёрдость у него иная."},{"h":"Как ведёт себя при фрезеровании","p":"Вязкая длинная стружка и склонность к налипанию могут быть важнее высокой твёрдости. Для тонкого финишного среза требуется достаточно острая кромка."},{"h":"Инструмент и выбор технологии","p":"Убедись, что канавки фрезы и СОЖ справляются с эвакуацией длинной стружки; на финише избегай продолжительного затирания."},{"h":"Типичные дефекты и причины","p":"Налипание и рваный край при неверной геометрии; заусенец на выходе; следы от стружки в кармане."},{"h":"Что проверить перед обработкой","p":"Состояние поставки, поверхностная обработка, требуемые допуски, наличие заусенцев. Важное ограничение: названия ГОСТ задают класс продукции и требования; реальные режимы резания и дефекты — технологические выводы, не табличные значения из стандарта."}],"linked":["mat-surface-layer","mat-hardness","mat-material-selection"],"sources":["grade-gost1050","mat-author"]},{"id":"mat-grade-steel-03","cat":"materials","title":"Сталь 20 — свойства и особенности фрезерования","subtitle":"Углеродистые стали","quick":"Качественная конструкционная углеродистая сталь. Одна из часто применяемых малоуглеродистых сталей для деталей машин; цифра отражает приблизительную углеродистость, а не фактическую твёрдость.","tags":["Сталь 20","20","Углеродистые стали","материал","марочник","обрабатываемость","режимы"],"time":11,"actions":["Проверь сертификат материала и нормируемое состояние, а не только название марки.","Сверь реальную твёрдость, структуру, форму и состояние наружного слоя.","Выбирай инструмент и режимы по подтверждённой группе и каталогу для конкретной операции.","Контролируй нагрузку, геометрию после разжима и характер износа."],"sections":[{"h":"Что это за марка","p":"Качественная конструкционная углеродистая сталь. Одна из часто применяемых малоуглеродистых сталей для деталей машин; цифра отражает приблизительную углеродистость, а не фактическую твёрдость."},{"h":"Состояние и термообработка","p":"В сыром и нормализованном состоянии свойства отличаются; после цементации поверхность может быть намного твёрже сердцевины."},{"h":"Как ведёт себя при фрезеровании","p":"При сравнительно невысокой твёрдости режущая кромка может страдать от налипания, а при наличии твёрдого слоя — от неоднородного контакта."},{"h":"Инструмент и выбор технологии","p":"Для поверхности после цементации не используй режимы, отработанные по мягкой сердцевине. На обычном прокате подбирай инструмент для сталей группы P."},{"h":"Типичные дефекты и причины","p":"Заусенцы и длинная стружка в мягком состоянии; повреждение кромки при проходе через твёрдый слой."},{"h":"Что проверить перед обработкой","p":"Состояние детали до или после химико-термической обработки; сертификат; HRC поверхности и сердцевины по требованию. Важное ограничение: названия ГОСТ задают класс продукции и требования; реальные режимы резания и дефекты — технологические выводы, не табличные значения из стандарта."}],"linked":["mat-case-hardening","mat-hardness","mat-material-selection"],"sources":["grade-gost1050","mat-author"]},{"id":"mat-grade-steel-04","cat":"materials","title":"Сталь 35 — свойства и особенности фрезерования","subtitle":"Углеродистые стали","quick":"Среднеуглеродистая конструкционная сталь. По углероду располагается между сталями 20 и 45; применяется для деталей машин с требованиями к прочности и термообработке.","tags":["Сталь 35","35","Углеродистые стали","материал","марочник","обрабатываемость","режимы"],"time":11,"actions":["Проверь сертификат материала и нормируемое состояние, а не только название марки.","Сверь реальную твёрдость, структуру, форму и состояние наружного слоя.","Выбирай инструмент и режимы по подтверждённой группе и каталогу для конкретной операции.","Контролируй нагрузку, геометрию после разжима и характер износа."],"sections":[{"h":"Что это за марка","p":"Среднеуглеродистая конструкционная сталь. По углероду располагается между сталями 20 и 45; применяется для деталей машин с требованиями к прочности и термообработке."},{"h":"Состояние и термообработка","p":"Нормализация, отжиг и закалка с отпуском приводят к разным твёрдостям и структурам, при одинаковой маркировке стали."},{"h":"Как ведёт себя при фрезеровании","p":"При росте прочности повышается нагрузка на кромку; на черновой важен стабильный контакт, на чистовой — отсутствие отжима."},{"h":"Инструмент и выбор технологии","p":"Выбирай исходную подгруппу ISO P по документированному состоянию, проверяй вылет фрезы и реальный ae в переходах."},{"h":"Типичные дефекты и причины","p":"Скол при непостоянном припуске; увод размера из-за прогиба; перегрев при неоправданно высокой Vc."},{"h":"Что проверить перед обработкой","p":"Сертификат, состояние поставки, твердость, число зубьев, жёсткость закрепления. Важное ограничение: названия ГОСТ задают класс продукции и требования; реальные режимы резания и дефекты — технологические выводы, не табличные значения из стандарта."}],"linked":["mat-hardness","mat-hardness","mat-material-selection"],"sources":["grade-gost1050","mat-author"]},{"id":"mat-grade-steel-05","cat":"materials","title":"Сталь 40 — свойства и особенности фрезерования","subtitle":"Углеродистые стали","quick":"Среднеуглеродистая качественная сталь, НЕ 40Х. Без буквы «Х» в названии — углеродистая сталь с ориентиром на 0,40% C. Это отдельная марка, а не сокращение 40Х.","tags":["Сталь 40","40","Углеродистые стали","материал","марочник","обрабатываемость","режимы"],"time":11,"actions":["Проверь сертификат материала и нормируемое состояние, а не только название марки.","Сверь реальную твёрдость, структуру, форму и состояние наружного слоя.","Выбирай инструмент и режимы по подтверждённой группе и каталогу для конкретной операции.","Контролируй нагрузку, геометрию после разжима и характер износа."],"sections":[{"h":"Что это за марка","p":"Среднеуглеродистая качественная сталь, НЕ 40Х. Без буквы «Х» в названии — углеродистая сталь с ориентиром на 0,40% C. Это отдельная марка, а не сокращение 40Х."},{"h":"Состояние и термообработка","p":"После нормализации, отжига, закалки и отпуска обрабатываемость меняется. Хромистая 40Х может иметь другую прокаливаемость и требовать иной технологии."},{"h":"Как ведёт себя при фрезеровании","p":"В нормализованном состоянии обычно обрабатывается как среднеуглеродистая сталь группы P. При повышенной твёрдости важны прочность кромки и недопущение локального полного паза."},{"h":"Инструмент и выбор технологии","p":"При построении процесса сразу разделяй 40 и 40Х в спецификации CAM. Не переносить автоматически найденные режимы для 40Х на сталь 40."},{"h":"Типичные дефекты и причины","p":"Ошибочная идентификация марки; непредсказуемый скол после термообработки; сильный перегрев при большой контактной зоне."},{"h":"Что проверить перед обработкой","p":"Проверь буквально записанную марку в чертеже и сертификате, HRC/HBW после термообработки и требования к структуре. Важное ограничение: названия ГОСТ задают класс продукции и требования; реальные режимы резания и дефекты — технологические выводы, не табличные значения из стандарта."}],"linked":["mat-steel-40kh","mat-hardness","mat-material-selection"],"sources":["grade-gost1050","mat-author"]},{"id":"mat-grade-steel-06","cat":"materials","title":"Сталь 45 — свойства и особенности фрезерования","subtitle":"Углеродистые стали","quick":"Очень распространённая качественная среднеуглеродистая сталь. Используется для валов, осей, шестерён и различных механических деталей. Номер указывает ориентир на массовую долю углерода порядка 0,45%.","tags":["Сталь 45","45","Углеродистые стали","материал","марочник","обрабатываемость","режимы"],"time":11,"actions":["Проверь сертификат материала и нормируемое состояние, а не только название марки.","Сверь реальную твёрдость, структуру, форму и состояние наружного слоя.","Выбирай инструмент и режимы по подтверждённой группе и каталогу для конкретной операции.","Контролируй нагрузку, геометрию после разжима и характер износа."],"sections":[{"h":"Что это за марка","p":"Очень распространённая качественная среднеуглеродистая сталь. Используется для валов, осей, шестерён и различных механических деталей. Номер указывает ориентир на массовую долю углерода порядка 0,45%."},{"h":"Состояние и термообработка","p":"На практике встречается в нормализованном, отожжённом, улучшенном или поверхностно закалённом состоянии; разница существенна."},{"h":"Как ведёт себя при фрезеровании","p":"На фрезеровании образует иной характер стружки и сил по сравнению с мягкой сталью 20. Если обработка ведётся после ТВЧ, учитывай градиент твёрдости."},{"h":"Инструмент и выбор технологии","p":"При черновой оцени припуск и жёсткость; при чистовой — реальные силы и состояние поверхностного слоя, особенно после закалки."},{"h":"Типичные дефекты и причины","p":"Ускоренный износ на упрочнённой поверхности; недостаточная плоскостность после снятия напряжений; перегрузка в углу."},{"h":"Что проверить перед обработкой","p":"HBW/HRC по нужной глубине, история термообработки, характер припуска и корки. Важное ограничение: названия ГОСТ задают класс продукции и требования; реальные режимы резания и дефекты — технологические выводы, не табличные значения из стандарта."}],"linked":["mat-case-hardening","mat-hardness","mat-material-selection"],"sources":["grade-gost1050","mat-author"]},{"id":"mat-grade-steel-07","cat":"materials","title":"09Г2С — свойства и особенности фрезерования","subtitle":"Низколегированные стали","quick":"Низколегированная конструкционная сталь повышенной прочности. Распространена в сварных конструкциях и прокате. Обозначение указывает на низкое содержание C с добавками марганца и кремния.","tags":["09Г2С","09Г2С","Низколегированные стали","материал","марочник","обрабатываемость","режимы"],"time":11,"actions":["Проверь сертификат материала и нормируемое состояние, а не только название марки.","Сверь реальную твёрдость, структуру, форму и состояние наружного слоя.","Выбирай инструмент и режимы по подтверждённой группе и каталогу для конкретной операции.","Контролируй нагрузку, геометрию после разжима и характер износа."],"sections":[{"h":"Что это за марка","p":"Низколегированная конструкционная сталь повышенной прочности. Распространена в сварных конструкциях и прокате. Обозначение указывает на низкое содержание C с добавками марганца и кремния."},{"h":"Состояние и термообработка","p":"Механические свойства зависят от толщины проката, категории поставки, технологии и термообработки; нельзя без уточнения считать её «всегда такой же, как Ст3»."},{"h":"Как ведёт себя при фрезеровании","p":"Технология фрезерования часто близка конструкционным сталям ISO P, но сварные детали могут иметь твёрдые локальные зоны, окалину и остаточные напряжения."},{"h":"Инструмент и выбор технологии","p":"Если фрезеруешь уже сваренную раму, учитывай зону термического влияния и деформацию после освобождения зажима."},{"h":"Типичные дефекты и причины","p":"Разная стойкость у шва и основного металла; коробление крупных плит; вибрации на неравномерной заготовке."},{"h":"Что проверить перед обработкой","p":"Состояние сварки, прокат, толщина, сертификат; текущая редакция ГОСТ 19281-2014 до 01.12.2026. Важное ограничение: названия ГОСТ задают класс продукции и требования; реальные режимы резания и дефекты — технологические выводы, не табличные значения из стандарта."}],"linked":["mat-stress","mat-hardness","mat-material-selection"],"sources":["grade-gost19281","mat-author"]},{"id":"mat-grade-steel-08","cat":"materials","title":"20Х — свойства и особенности фрезерования","subtitle":"Легированные стали","quick":"Низкоуглеродистая легированная хромистая конструкционная сталь. Хромистая сталь, часто применяемая для деталей, которые затем цементуют или поверхностно упрочняют, сохраняя вязкую сердцевину.","tags":["20Х","20Х","Легированные стали","материал","марочник","обрабатываемость","режимы"],"time":11,"actions":["Проверь сертификат материала и нормируемое состояние, а не только название марки.","Сверь реальную твёрдость, структуру, форму и состояние наружного слоя.","Выбирай инструмент и режимы по подтверждённой группе и каталогу для конкретной операции.","Контролируй нагрузку, геометрию после разжима и характер износа."],"sections":[{"h":"Что это за марка","p":"Низкоуглеродистая легированная хромистая конструкционная сталь. Хромистая сталь, часто применяемая для деталей, которые затем цементуют или поверхностно упрочняют, сохраняя вязкую сердцевину."},{"h":"Состояние и термообработка","p":"Маршрут «мягкая обработка → цементация → закалка → финиш» принципиально отличается от фрезерования готовой упрочнённой поверхности."},{"h":"Как ведёт себя при фрезеровании","p":"До упрочнения контролируй пластичную стружку и форму. После — градиент твёрдости и инструментальный материал на участке входа."},{"h":"Инструмент и выбор технологии","p":"На чертеже ищи требования к глубине цементованного слоя и к размерам до/после термообработки. Технологический припуск назначается по маршруту."},{"h":"Типичные дефекты и причины","p":"Скол при прохождении твёрдой корки; потеря функционального слоя от лишнего прохода; коробление после закалки."},{"h":"Что проверить перед обработкой","p":"Режим цементации, эффективная глубина слоя, твёрдость поверхности/сердцевины, предельный припуск. Важное ограничение: названия ГОСТ задают класс продукции и требования; реальные режимы резания и дефекты — технологические выводы, не табличные значения из стандарта."}],"linked":["mat-case-hardening","mat-hardness","mat-material-selection"],"sources":["grade-gost4543","mat-author"]},{"id":"mat-grade-steel-09","cat":"materials","title":"65Г — свойства и особенности фрезерования","subtitle":"Пружинные стали","quick":"Рессорно-пружинная марганцовистая сталь. Высокоуглеродистая пружинная сталь, востребованная в упругих деталях, пластинах и элементах пружинной оснастки.","tags":["65Г","65Г","Пружинные стали","материал","марочник","обрабатываемость","режимы"],"time":11,"actions":["Проверь сертификат материала и нормируемое состояние, а не только название марки.","Сверь реальную твёрдость, структуру, форму и состояние наружного слоя.","Выбирай инструмент и режимы по подтверждённой группе и каталогу для конкретной операции.","Контролируй нагрузку, геометрию после разжима и характер износа."],"sections":[{"h":"Что это за марка","p":"Рессорно-пружинная марганцовистая сталь. Высокоуглеродистая пружинная сталь, востребованная в упругих деталях, пластинах и элементах пружинной оснастки."},{"h":"Состояние и термообработка","p":"Состояние после проката, отжига и закалки с отпуском совершенно разное; готовые упругие пластины могут сильно деформироваться при зажиме."},{"h":"Как ведёт себя при фрезеровании","p":"При высокой твёрдости растёт риск скола; у тонкой детали основным ограничением становится удержание формы при снятии металла."},{"h":"Инструмент и выбор технологии","p":"До выбора фрезы проверь целевую твёрдость, профиль детали, её опоры и момент отпуска в техпроцессе."},{"h":"Типичные дефекты и причины","p":"Конусность и прогиб тонких пластин; трещины в материале после неверной термообработки; выкрашивание кромки."},{"h":"Что проверить перед обработкой","p":"Состояние, HRC по спецификации, толщина детали, способ фиксации без избыточной деформации. Важное ограничение: названия ГОСТ задают класс продукции и требования; реальные режимы резания и дефекты — технологические выводы, не табличные значения из стандарта."}],"linked":["mat-heat-treat","mat-hardness","mat-material-selection"],"sources":["grade-gost14959","mat-author"]},{"id":"mat-grade-steel-10","cat":"materials","title":"ШХ15 — свойства и особенности фрезерования","subtitle":"Подшипниковые стали","quick":"Высокоуглеродистая хромистая подшипниковая сталь. Используется для тел качения, колец и высоконагруженных точных деталей. Важны не только твёрдость, но и карбидная структура, чистота и включения.","tags":["ШХ15","ШХ15","Подшипниковые стали","материал","марочник","обрабатываемость","режимы"],"time":11,"actions":["Проверь сертификат материала и нормируемое состояние, а не только название марки.","Сверь реальную твёрдость, структуру, форму и состояние наружного слоя.","Выбирай инструмент и режимы по подтверждённой группе и каталогу для конкретной операции.","Контролируй нагрузку, геометрию после разжима и характер износа."],"sections":[{"h":"Что это за марка","p":"Высокоуглеродистая хромистая подшипниковая сталь. Используется для тел качения, колец и высоконагруженных точных деталей. Важны не только твёрдость, но и карбидная структура, чистота и включения."},{"h":"Состояние и термообработка","p":"В сфероидизированном состоянии может обрабатываться до закалки; после получения рабочей высокой твёрдости методы и инструмент радикально отличаются."},{"h":"Как ведёт себя при фрезеровании","p":"Из-за карбидов и твёрдости определяющими становятся износостойкость кромки, геометрия и строго контролируемые припуски."},{"h":"Инструмент и выбор технологии","p":"Разделяй обработку мягкой заготовки и окончательной подшипниковой детали после термообработки. Не ориентируйся на одну цифру HRC."},{"h":"Типичные дефекты и причины","p":"Быстрый износ на мелких твёрдых частицах; скол на прерывистом резании; перегрев на финише."},{"h":"Что проверить перед обработкой","p":"ГОСТ 801-2022, состояние поставки, чистота и структура по требованиям, HRC и качество поверхности. Важное ограничение: названия ГОСТ задают класс продукции и требования; реальные режимы резания и дефекты — технологические выводы, не табличные значения из стандарта."}],"linked":["mat-hardness","mat-hardness","mat-material-selection"],"sources":["grade-gost801","mat-author"]},{"id":"mat-grade-steel-11","cat":"materials","title":"08Х18Н10 — свойства и особенности фрезерования","subtitle":"Нержавеющие стали","quick":"Аустенитная коррозионностойкая хромоникелевая сталь. Распространённая Cr–Ni нержавеющая сталь группы M. Сравнима по типу структуры с 12Х18Н10Т, но не тождественна ей по составу и назначению.","tags":["08Х18Н10","08Х18Н10","Нержавеющие стали","материал","марочник","обрабатываемость","режимы"],"time":11,"actions":["Проверь сертификат материала и нормируемое состояние, а не только название марки.","Сверь реальную твёрдость, структуру, форму и состояние наружного слоя.","Выбирай инструмент и режимы по подтверждённой группе и каталогу для конкретной операции.","Контролируй нагрузку, геометрию после разжима и характер износа."],"sections":[{"h":"Что это за марка","p":"Аустенитная коррозионностойкая хромоникелевая сталь. Распространённая Cr–Ni нержавеющая сталь группы M. Сравнима по типу структуры с 12Х18Н10Т, но не тождественна ей по составу и назначению."},{"h":"Состояние и термообработка","p":"В отожжённом состоянии структура обычно аустенитная. Холодная деформация может увеличить прочность и изменить реакцию на инструмент."},{"h":"Как ведёт себя при фрезеровании","p":"Склонность к наклёпу и налипанию; относительно невысокая теплопроводность усиливает тепловую нагрузку на кромке."},{"h":"Инструмент и выбор технологии","p":"Подбирай геометрию под группу M, не допускай повторного затирания, проверяй достаточную толщину стружки и направление СОЖ."},{"h":"Типичные дефекты и причины","p":"Рваная поверхность, стойкий нарост и ухудшение финиша при слишком малом срезе."},{"h":"Что проверить перед обработкой","p":"Подтверди 08Х18Н10 vs 12Х18Н10Т, исходный наклёп, состояние/поверхность и требования к коррозионной стойкости. Важное ограничение: названия ГОСТ задают класс продукции и требования; реальные режимы резания и дефекты — технологические выводы, не табличные значения из стандарта."}],"linked":["mat-stainless-12kh18n10t","mat-hardness","mat-material-selection"],"sources":["grade-gost5632","mat-author"]},{"id":"mat-grade-steel-12","cat":"materials","title":"20Х13 — свойства и особенности фрезерования","subtitle":"Нержавеющие стали","quick":"Мартенситная коррозионностойкая хромистая сталь. Отличается от аустенитных Cr–Ni сталей: допускает термическое упрочнение, и её обрабатываемость сильно зависит от этого состояния.","tags":["20Х13","20Х13","Нержавеющие стали","материал","марочник","обрабатываемость","режимы"],"time":11,"actions":["Проверь сертификат материала и нормируемое состояние, а не только название марки.","Сверь реальную твёрдость, структуру, форму и состояние наружного слоя.","Выбирай инструмент и режимы по подтверждённой группе и каталогу для конкретной операции.","Контролируй нагрузку, геометрию после разжима и характер износа."],"sections":[{"h":"Что это за марка","p":"Мартенситная коррозионностойкая хромистая сталь. Отличается от аустенитных Cr–Ni сталей: допускает термическое упрочнение, и её обрабатываемость сильно зависит от этого состояния."},{"h":"Состояние и термообработка","p":"В отожжённом и закалённо-отпущенном состоянии будет иной набор HRC, микроструктуры и сил резания."},{"h":"Как ведёт себя при фрезеровании","p":"В мягком состоянии подбирают инструмент как для соответствующей хромистой стали; после упрочнения кромка должна выдерживать более высокую нагрузку."},{"h":"Инструмент и выбор технологии","p":"Обязательно уточняй состояние, прежде чем применять режимы из «нержавейки 304»."},{"h":"Типичные дефекты и причины","p":"Ускоренный износ после закалки; сколы на прерывистом контуре; несоответствие финишной геометрии из-за прогиба."},{"h":"Что проверить перед обработкой","p":"Термообработка, фактическая HRC, требования к коррозионной стойкости и точности. Важное ограничение: названия ГОСТ задают класс продукции и требования; реальные режимы резания и дефекты — технологические выводы, не табличные значения из стандарта."}],"linked":["mat-stainless-families","mat-hardness","mat-material-selection"],"sources":["grade-gost5632","mat-author"]},{"id":"mat-grade-steel-13","cat":"materials","title":"40Х13 — свойства и особенности фрезерования","subtitle":"Нержавеющие стали","quick":"Высокоуглеродистая мартенситная хромистая сталь. Встречается в деталях, где нужны повышенная твёрдость и коррозионная стойкость; не является эквивалентом 40Х.","tags":["40Х13","40Х13","Нержавеющие стали","материал","марочник","обрабатываемость","режимы"],"time":11,"actions":["Проверь сертификат материала и нормируемое состояние, а не только название марки.","Сверь реальную твёрдость, структуру, форму и состояние наружного слоя.","Выбирай инструмент и режимы по подтверждённой группе и каталогу для конкретной операции.","Контролируй нагрузку, геометрию после разжима и характер износа."],"sections":[{"h":"Что это за марка","p":"Высокоуглеродистая мартенситная хромистая сталь. Встречается в деталях, где нужны повышенная твёрдость и коррозионная стойкость; не является эквивалентом 40Х."},{"h":"Состояние и термообработка","p":"После закалки может быть существенно твёрже сырой хромистой стали; характер карбидов и отпуск определяют износ инструмента."},{"h":"Как ведёт себя при фрезеровании","p":"При большой твёрдости работа фрезы ограничивается прочностью режущей кромки и нагревом, особенно на острых внутренних углах."},{"h":"Инструмент и выбор технологии","p":"Сначала проверь HRC и режущий материал, затем решай, допустима ли монолитная фреза на нужной осевой глубине."},{"h":"Типичные дефекты и причины","p":"Микросколы после ударных входов, термический износ, нестабильный размер."},{"h":"Что проверить перед обработкой","p":"Не перепутай с 40Х; проверь структурное состояние, HRC и рабочую длину фрезы. Важное ограничение: названия ГОСТ задают класс продукции и требования; реальные режимы резания и дефекты — технологические выводы, не табличные значения из стандарта."}],"linked":["mat-steel-40kh","mat-hardness","mat-material-selection"],"sources":["grade-gost5632","mat-author"]},{"id":"mat-grade-steel-14","cat":"materials","title":"95Х18 — свойства и особенности фрезерования","subtitle":"Нержавеющие стали","quick":"Высокоуглеродистая мартенситная коррозионностойкая сталь. Марка с высоким содержанием хрома и углерода, в структуре которой важны твёрдые карбиды; применяется для износостойких деталей.","tags":["95Х18","95Х18","Нержавеющие стали","материал","марочник","обрабатываемость","режимы"],"time":11,"actions":["Проверь сертификат материала и нормируемое состояние, а не только название марки.","Сверь реальную твёрдость, структуру, форму и состояние наружного слоя.","Выбирай инструмент и режимы по подтверждённой группе и каталогу для конкретной операции.","Контролируй нагрузку, геометрию после разжима и характер износа."],"sections":[{"h":"Что это за марка","p":"Высокоуглеродистая мартенситная коррозионностойкая сталь. Марка с высоким содержанием хрома и углерода, в структуре которой важны твёрдые карбиды; применяется для износостойких деталей."},{"h":"Состояние и термообработка","p":"В отожжённом состоянии обрабатывается совсем иначе, чем после закалки и отпуска. Поверхностная твёрдость не описывает распределение карбидов."},{"h":"Как ведёт себя при фрезеровании","p":"При фрезеровании в упрочнённом состоянии риск абразивного износа и скола повышается; режим выбирают под конкретный инструмент."},{"h":"Инструмент и выбор технологии","p":"Не переносить методы от аустенитной 12Х18Н10Т: её трудности — наклёп и пластичность, а здесь также доминируют твёрдые частицы."},{"h":"Типичные дефекты и причины","p":"Сколы и абразивный износ на карбидах; задиры при изношенной кромке."},{"h":"Что проверить перед обработкой","p":"Состояние, структура и карбиды, разрешённая твёрдость, инструмент и качество финиша. Важное ограничение: названия ГОСТ задают класс продукции и требования; реальные режимы резания и дефекты — технологические выводы, не табличные значения из стандарта."}],"linked":["mat-stainless-families","mat-hardness","mat-material-selection"],"sources":["grade-gost5632","mat-author"]},{"id":"mat-grade-steel-15","cat":"materials","title":"Х12МФ — свойства и особенности фрезерования","subtitle":"Инструментальные стали","quick":"Высокохромистая инструментальная сталь холодной работы. Используется для штампов и износостойкой оснастки. Крупные и мелкие карбиды существенно влияют на поведение при обработке.","tags":["Х12МФ","Х12МФ","Инструментальные стали","материал","марочник","обрабатываемость","режимы"],"time":11,"actions":["Проверь сертификат материала и нормируемое состояние, а не только название марки.","Сверь реальную твёрдость, структуру, форму и состояние наружного слоя.","Выбирай инструмент и режимы по подтверждённой группе и каталогу для конкретной операции.","Контролируй нагрузку, геометрию после разжима и характер износа."],"sections":[{"h":"Что это за марка","p":"Высокохромистая инструментальная сталь холодной работы. Используется для штампов и износостойкой оснастки. Крупные и мелкие карбиды существенно влияют на поведение при обработке."},{"h":"Состояние и термообработка","p":"До закалки и после неё применяются разные стратегии; после термообработки нередко требуется окончательная точная обработка твёрдого инструмента."},{"h":"Как ведёт себя при фрезеровании","p":"Повышенная абразивность и возможная неоднородность структуры дают износ и сколы; необходимо согласовывать обработку с предполагаемой последующей термообработкой."},{"h":"Инструмент и выбор технологии","p":"Для карманов и формообразующих поверхностей анализируй твёрдость, карбидность, слабые участки и равномерность припуска."},{"h":"Типичные дефекты и причины","p":"Выкрашивание кромки на включениях, нестабильная шероховатость, коробление после закалки."},{"h":"Что проверить перед обработкой","p":"Состояние отжига/закалки, структура по техтребованиям, режим отпуска и материал фрезы. Важное ограничение: названия ГОСТ задают класс продукции и требования; реальные режимы резания и дефекты — технологические выводы, не табличные значения из стандарта."}],"linked":["mat-microstructure","mat-hardness","mat-material-selection"],"sources":["grade-gost5950","mat-author"]},{"id":"mat-grade-steel-16","cat":"materials","title":"9ХС — свойства и особенности фрезерования","subtitle":"Инструментальные стали","quick":"Легированная инструментальная сталь для режущего и мерительного инструмента. Сталь с хромом и кремнием, применяемая для инструмента и точной оснастки; изготавливают в разных термообработанных состояниях.","tags":["9ХС","9ХС","Инструментальные стали","материал","марочник","обрабатываемость","режимы"],"time":11,"actions":["Проверь сертификат материала и нормируемое состояние, а не только название марки.","Сверь реальную твёрдость, структуру, форму и состояние наружного слоя.","Выбирай инструмент и режимы по подтверждённой группе и каталогу для конкретной операции.","Контролируй нагрузку, геометрию после разжима и характер износа."],"sections":[{"h":"Что это за марка","p":"Легированная инструментальная сталь для режущего и мерительного инструмента. Сталь с хромом и кремнием, применяемая для инструмента и точной оснастки; изготавливают в разных термообработанных состояниях."},{"h":"Состояние и термообработка","p":"После отжига можно готовить геометрию, а последующая закалка приводит к иной стойкости и размерному состоянию."},{"h":"Как ведёт себя при фрезеровании","p":"Для фрезеровщика критичны твёрдость, условия резания и требования к точности после термообработки."},{"h":"Инструмент и выбор технологии","p":"Учитывай изменение размеров после закалки и возможное наличие твёрдых участков на поверхности."},{"h":"Типичные дефекты и причины","p":"Сколы после закалки, быстрый износ, уход размера при снятии напряжений."},{"h":"Что проверить перед обработкой","p":"Фактическая HRC, термообработка, маршрут последующей доводки, оставленный припуск. Важное ограничение: названия ГОСТ задают класс продукции и требования; реальные режимы резания и дефекты — технологические выводы, не табличные значения из стандарта."}],"linked":["mat-heat-treat","mat-hardness","mat-material-selection"],"sources":["grade-gost5950","mat-author"]},{"id":"mat-grade-steel-17","cat":"materials","title":"Р6М5 — свойства и особенности фрезерования","subtitle":"Быстрорежущие стали","quick":"Быстрорежущая инструментальная сталь. Классическая быстрорежущая сталь для режущих инструментов; название связано с её легированием, а не обозначением обычной конструкционной стали.","tags":["Р6М5","Р6М5","Быстрорежущие стали","материал","марочник","обрабатываемость","режимы"],"time":11,"actions":["Проверь сертификат материала и нормируемое состояние, а не только название марки.","Сверь реальную твёрдость, структуру, форму и состояние наружного слоя.","Выбирай инструмент и режимы по подтверждённой группе и каталогу для конкретной операции.","Контролируй нагрузку, геометрию после разжима и характер износа."],"sections":[{"h":"Что это за марка","p":"Быстрорежущая инструментальная сталь. Классическая быстрорежущая сталь для режущих инструментов; название связано с её легированием, а не обозначением обычной конструкционной стали."},{"h":"Состояние и термообработка","p":"До упрочнения это заготовка инструмента, после правильной термообработки — твёрдый материал с карбидами и стойкостью при нагреве."},{"h":"Как ведёт себя при фрезеровании","p":"На фрезеровании уже закалённой Р6М5 возможны значительные трудности; не применять к ней режимы обычных конструкционных сталей."},{"h":"Инструмент и выбор технологии","p":"Если производишь фрезу или резец из Р6М5, отдельно проектируй мягкую обработку, термообработку и последующую точную обработку."},{"h":"Типичные дефекты и причины","p":"Абразивный износ, скол твёрдой кромки, потеря качества при перегреве."},{"h":"Что проверить перед обработкой","p":"Режим закалки/отпуска, измеренная HRC, карбидность, контроль формы. Важное ограничение: названия ГОСТ задают класс продукции и требования; реальные режимы резания и дефекты — технологические выводы, не табличные значения из стандарта."}],"linked":["mat-hardness","mat-hardness","mat-material-selection"],"sources":["grade-gost19265","mat-author"]}];const gradeSet=new Set(d.materialGradeAtlas.map(g=>g.id));for(const g of grades)if(!gradeSet.has(g.id)){d.materialGradeAtlas.push(g);gradeSet.add(g.id)}const seen=new Set(d.articles.map(a=>a.id));for(const a of articles)if(!seen.has(a.id)){d.articles.push(a);seen.add(a.id);}})();